// ============================================================================
// Constants
// ============================================================================

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;

// ============================================================================
// Name Helpers
// ============================================================================

function toKebab(name: string): string {
  return name
    .replace(/([a-z])([A-Z])/g, '$1-$2')
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

function toSnake(name: string): string {
  return toKebab(name).replace(/-/g, '_');
}

function toPascal(name: string): string {
  return name
    .replace(/(?:^|[-_\s])(\w)/g, (_, c: string) => (c as string).toUpperCase())
    .replace(/[^a-zA-Z0-9]/g, '');
}

function toCtxSlug(contextName: string): string {
  return toKebab(contextName.replace(/Context$/i, ''));
}

function toCtxSnake(contextName: string): string {
  return toSnake(contextName.replace(/Context$/i, ''));
}

/**
 * Sanitize a raw type string from mock contracts into a valid TypeScript type.
 */
function sanitizeType(raw: string | undefined, fallback: string): string {
  if (!raw || raw === 'void') return 'void';
  const trimmed = raw.trim();
  if (/^[A-Z]/.test(trimmed) || /^(?:void|string|number|boolean|null|undefined|Record<|Array<|Promise<)/.test(trimmed)) {
    return trimmed;
  }
  if (trimmed.includes(':')) {
    const afterColon = trimmed.split(':').pop()?.trim();
    if (afterColon && /^[A-Za-z]/.test(afterColon)) return afterColon;
  }
  if (/^[a-z][a-z0-9]*$/i.test(trimmed)) return fallback;
  return fallback;
}

/**
 * Clean a raw method name from mock contracts.
 * Handles "POST /context/create-thing" → "createThing"
 */
function cleanMethodName(raw: string): string {
  // Strip HTTP verb prefix
  const withoutVerb = raw.replace(/^\s*(GET|POST|PUT|PATCH|DELETE)\s+/i, '');
  // Extract last path segment
  const segments = withoutVerb.split('/').filter(Boolean);
  const last = segments[segments.length - 1] ?? raw;
  const cleaned = last.replace(/[^a-zA-Z0-9-_]/g, '');
  if (!cleaned) return 'execute';
  // kebab-case to camelCase
  return cleaned
    .replace(/[-_]+(.)?/g, (_: string, c: string | undefined) => (c ? c.toUpperCase() : ''))
    .replace(/^(.)/, (_: string, c: string) => c.toLowerCase());
}

// ============================================================================
// TypeScript Port Interface Generation (domain-specific)
// ============================================================================

/**
 * Generate a TypeScript port interface with proper DTOs and method signatures.
 */
function generateTypescriptPort(
  portBaseName: string,
  boundedContext: string,
  mockContract?: { methods: readonly { name: string; input: string; output: string; behavior: string }[] },
): string {
  const interfaceName = 'I' + toPascal(portBaseName) + 'Port';
  const ctxPascal = toPascal(boundedContext);

  const dtoTypes = new Set<string>();
  let methodSigs: string;

  if (mockContract && mockContract.methods.length > 0) {
    methodSigs = mockContract.methods
      .map((m) => {
        const methodName = cleanMethodName(m.name);
        const inputType = sanitizeType(m.input, `${ctxPascal}Input`);
        const outputType = sanitizeType(m.output, ctxPascal);

        for (const t of [inputType, outputType]) {
          const base = t.replace(/\[\]$/, '');
          if (base !== 'void' && !/^(?:string|number|boolean|null|undefined|object|Record<.*>|Array<.*>)$/.test(base)) {
            dtoTypes.add(base);
          }
        }

        return `  /** ${m.behavior} */\n  ${methodName}(input: ${inputType}): Promise<${outputType}>;`;
      })
      .join('\n\n');
  } else {
    // Fallback: standard CRUD port
    dtoTypes.add(ctxPascal);
    dtoTypes.add(`${ctxPascal}Input`);
    methodSigs = [
      `  findById(id: string): Promise<${ctxPascal} | null>;`,
      `  findAll(filters?: Record<string, unknown>): Promise<${ctxPascal}[]>;`,
      `  save(input: ${ctxPascal}Input): Promise<${ctxPascal}>;`,
      `  deleteById(id: string): Promise<void>;`,
    ].join('\n');
  }

  const dtoStubs = [...dtoTypes].map((typeName) =>
    `export interface ${typeName} {\n  readonly [key: string]: unknown;\n}`
  ).join('\n\n');

  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `/**`,
    ` * Port interface for bounded context: ${boundedContext}`,
    ` */`,
    ``,
    ...(dtoStubs ? [dtoStubs, ''] : []),
    `export interface ${interfaceName} {`,
    methodSigs,
    `}`,
    ``,
  ].join('\n');
}

// ============================================================================
// TypeScript Adapter Code Generation
// ============================================================================

/**
 * Generate a TypeScript adapter class that implements a port interface.
 * Uses project-local imports, typed constructor deps, parameterized SQL,
 * and OpenTelemetry spans via the local telemetry module.
 */
function generateTypescriptAdapter(
  portFileName: string,
  boundedContext: string,
  erpSystem: string,
  mockContract?: { methods: readonly { name: string; input: string; output: string; behavior: string }[] },
): string {
  const baseName = portFileName.replace(/\.ts$/, '');
  const className = toPascal(baseName) + 'Adapter';
  const interfaceName = 'I' + toPascal(baseName) + 'Port';
  const ctxPascal = toPascal(boundedContext);
  const ctxSnake = toSnake(boundedContext);
  const tableName = toSnake(baseName);

  // Collect DTO types referenced by the port
  const dtoImports = new Set<string>();

  let methodImpls: string;
  if (mockContract && mockContract.methods.length > 0) {
    methodImpls = mockContract.methods
      .map((m) => {
        const methodName = cleanMethodName(m.name);
        const inputType = sanitizeType(m.input, `${ctxPascal}Input`);
        const outputType = sanitizeType(m.output, ctxPascal);
        const isQuery = /^(?:get|find|list|query|search|fetch)/.test(methodName);

        for (const t of [inputType, outputType]) {
          const base = t.replace(/\[\]$/, '');
          if (base !== 'void' && !/^(?:string|number|boolean|null|undefined|object|Record<.*>|Array<.*>)$/.test(base)) {
            dtoImports.add(base);
          }
        }

        if (isQuery) {
          return [
            ``,
            `  /** ${m.behavior} */`,
            `  async ${methodName}(input: ${inputType}): Promise<${outputType}> {`,
            `    return this.telemetry.withSpan('${ctxSnake}', '${methodName}', {}, async () => {`,
            `      const rows = await this.db.query(`,
            `        'SELECT * FROM ${tableName} WHERE 1=1',`,
            `        [],`,
            `      );`,
            `      return rows as unknown as ${outputType};`,
            `    });`,
            `  }`,
          ].join('\n');
        }

        return [
          ``,
          `  /** ${m.behavior} */`,
          `  async ${methodName}(input: ${inputType}): Promise<${outputType}> {`,
          `    return this.telemetry.withSpan('${ctxSnake}', '${methodName}', {}, async () => {`,
          `      const result = await this.erp.invoke('${methodName}', input);`,
          `      return result as unknown as ${outputType};`,
          `    });`,
          `  }`,
        ].join('\n');
      })
      .join('\n');
  } else {
    // Fallback: standard CRUD adapter
    dtoImports.add(ctxPascal);
    dtoImports.add(`${ctxPascal}Input`);
    methodImpls = [
      ``,
      `  async findById(id: string): Promise<${ctxPascal} | null> {`,
      `    return this.telemetry.withSpan('${ctxSnake}', 'findById', { id }, async () => {`,
      `      const rows = await this.db.query(`,
      `        'SELECT * FROM ${tableName} WHERE id = :1',`,
      `        [id],`,
      `      );`,
      `      return (rows[0] as ${ctxPascal}) ?? null;`,
      `    });`,
      `  }`,
      ``,
      `  async findAll(filters?: Record<string, unknown>): Promise<${ctxPascal}[]> {`,
      `    return this.telemetry.withSpan('${ctxSnake}', 'findAll', {}, async () => {`,
      `      const rows = await this.db.query(`,
      `        'SELECT * FROM ${tableName}',`,
      `        [],`,
      `      );`,
      `      return rows as unknown as ${ctxPascal}[];`,
      `    });`,
      `  }`,
      ``,
      `  async save(input: ${ctxPascal}Input): Promise<${ctxPascal}> {`,
      `    return this.telemetry.withSpan('${ctxSnake}', 'save', {}, async () => {`,
      `      const result = await this.erp.invoke('save', input);`,
      `      return result as unknown as ${ctxPascal};`,
      `    });`,
      `  }`,
      ``,
      `  async deleteById(id: string): Promise<void> {`,
      `    return this.telemetry.withSpan('${ctxSnake}', 'deleteById', { id }, async () => {`,
      `      await this.db.execute(`,
      `        'DELETE FROM ${tableName} WHERE id = :1',`,
      `        [id],`,
      `      );`,
      `    });`,
      `  }`,
    ].join('\n');
  }

  const dtoImportList = dtoImports.size > 0
    ? `import type { ${interfaceName}, ${[...dtoImports].join(', ')} } from '../ports/${baseName}.js';`
    : `import type { ${interfaceName} } from '../ports/${baseName}.js';`;

  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `${dtoImportList}`,
    `import type { Telemetry } from '../../infra/telemetry.js';`,
    `import type { DbClient, ErpClient } from '../../infra/clients.js';`,
    ``,
    `/**`,
    ` * Infrastructure adapter: ${className}`,
    ` * Bounded context: ${boundedContext}`,
    ` * ERP system: ${erpSystem}`,
    ` *`,
    ` * Bridges the ${interfaceName} port to the ${erpSystem} ERP system`,
    ` * and the underlying database client.`,
    ` */`,
    `export class ${className} implements ${interfaceName} {`,
    `  constructor(`,
    `    private readonly db: DbClient,`,
    `    private readonly erp: ErpClient,`,
    `    private readonly telemetry: Telemetry,`,
    `  ) {}`,
    methodImpls,
    `}`,
    ``,
  ].join('\n');
}

