/**
 * Generate a TypeScript IAM helper that fetches a GCP identity token.
 */
function generateTypescriptIAMHelper(): string {
  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `/**`,
    ` * GCP Identity Token Helper`,
    ` *`,
    ` * Fetches a short-lived identity token from the GCP metadata server`,
    ` * for service-to-service authentication.`,
    ` */`,
    ``,
    `const METADATA_TOKEN_URL =`,
    `  'http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity';`,
    ``,
    `export async function fetchIdentityToken(audience: string): Promise<string> {`,
    `  const url = \`\${METADATA_TOKEN_URL}?audience=\${encodeURIComponent(audience)}&format=full\`;`,
    ``,
    `  const response = await fetch(url, {`,
    `    headers: { 'Metadata-Flavor': 'Google' },`,
    `  });`,
    ``,
    `  if (!response.ok) {`,
    `    throw new Error(`,
    `      \`Failed to fetch identity token: HTTP \${response.status}\`,`,
    `    );`,
    `  }`,
    ``,
    `  return response.text();`,
    `}`,
    ``,
  ].join('\n');
}

// ============================================================================
// Rust Adapter Code Generation
// ============================================================================

function generateRustAdapter(
  portFileName: string,
  boundedContext: string,
  erpSystem: string,
): string {
  const baseName = portFileName.replace(/\.rs$/, '');
  const structName = toPascal(baseName) + 'Adapter';
  const traitName = 'I' + toPascal(baseName) + 'Port';
  const snakeName = toSnake(baseName);

  return [
    `// Generated by Phase 4 pipeline — do not edit manually`,
    ``,
    `//! Infrastructure adapter: ${structName}`,
    `//! Bounded context: ${boundedContext}`,
    `//! ERP system: ${erpSystem}`,
    ``,
    `use crate::ports::${baseName}::${traitName};`,
    `use tracing::{info_span, Instrument};`,
    ``,
    `#[async_trait::async_trait]`,
    `pub trait DbClient: Send + Sync {`,
    `    async fn query(&self, sql: &str, params: &[&(dyn std::any::Any + Send + Sync)]) -> Result<Vec<serde_json::Value>, Box<dyn std::error::Error>>;`,
    `    async fn execute(&self, sql: &str, params: &[&(dyn std::any::Any + Send + Sync)]) -> Result<(), Box<dyn std::error::Error>>;`,
    `}`,
    ``,
    `#[async_trait::async_trait]`,
    `pub trait ErpClient: Send + Sync {`,
    `    async fn invoke(&self, operation: &str, data: serde_json::Value) -> Result<serde_json::Value, Box<dyn std::error::Error>>;`,
    `}`,
    ``,
    `pub struct ${structName} {`,
    `    db_client: Box<dyn DbClient>,`,
    `    erp_client: Box<dyn ErpClient>,`,
    `}`,
    ``,
    `impl ${structName} {`,
    `    pub fn new(db_client: Box<dyn DbClient>, erp_client: Box<dyn ErpClient>) -> Self {`,
    `        Self { db_client, erp_client }`,
    `    }`,
    ``,
    `    pub async fn find_by_id(&self, id: &str) -> Result<Option<serde_json::Value>, Box<dyn std::error::Error>> {`,
    `        let span = info_span!("${snakeName}.find_by_id", id = %id);`,
    `        async {`,
    `            let results = self.db_client.query(`,
    `                "SELECT * FROM ${snakeName} WHERE id = :1",`,
    `                &[&id as &(dyn std::any::Any + Send + Sync)],`,
    `            ).await?;`,
    `            Ok(results.into_iter().next())`,
    `        }.instrument(span).await`,
    `    }`,
    ``,
    `    pub async fn save(&self, data: serde_json::Value) -> Result<(), Box<dyn std::error::Error>> {`,
    `        let id = data.get("id").and_then(|v| v.as_str()).unwrap_or("unknown");`,
    `        let span = info_span!("${snakeName}.save", id = %id);`,
    `        async {`,
    `            self.db_client.execute(`,
    `                "MERGE INTO ${snakeName} USING DUAL ON (id = :1) WHEN MATCHED THEN UPDATE SET updated_at = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (id) VALUES (:1)",`,
    `                &[&id as &(dyn std::any::Any + Send + Sync)],`,
    `            ).await`,
    `        }.instrument(span).await`,
    `    }`,
    `}`,
    ``,
    `#[async_trait::async_trait]`,
    `impl ${traitName} for ${structName} {`,
    `    // Trait methods delegate to the internal find_by_id/save/erp_client methods`,
    `    // with full tracing instrumentation.`,
    `}`,
    ``,
  ].join('\n');
}

